en:
//【景明】
<voice name='景明' class='景明' src='voice/md01/0300300a00'>
//「……当然の言葉だ」
"...What do you expect?"

pt:
//【景明】
<voice name='景明' class='景明' src='voice/md01/0300300a00'>
//「……当然の言葉だ」
"...O que você esperava?"

en:
//　彼は知らないのだから。
//　まだ気付いていないのだから。
  He doesn't know. It hasn't yet dawned on him what he is facing.

pt:
//　彼は知らないのだから。
//　まだ気付いていないのだから。
  Ele não sabe. Ainda não se deu conta do que está enfrentando.

en:
//【光】
<voice name='光' class='光' src='voice/md01/0300310a14'>
//「おまえに言われると傷つく……」
"That hurts, coming from you..."

pt:
//【光】
<voice name='光' class='光' src='voice/md01/0300310a14'>
//「おまえに言われると傷つく……」
"Isso machuca, vindo de você..."

en:
//【護氏】
<voice name='護氏' class='護氏' src='voice/md01/0300320a05'>
//「予を愚弄する気かッ！」
"You mock me!?"

pt:
//【護氏】
<voice name='護氏' class='護氏' src='voice/md01/0300320a05'>
